changeSet.sql:
-- 1. Дропаем старые FK (без CASCADE)
ALTER TABLE `index` DROP FOREIGN KEY FK3uxy5s82mxfodai0iafb232cs;
ALTER TABLE `index` DROP FOREIGN KEY FKiqgm34dkvjdt7kobg71xlbr33;

-- 2. Очистка таблиц (порядок: index -> lemma, page)
TRUNCATE TABLE `index`;
TRUNCATE TABLE lemma;
TRUNCATE TABLE page;

-- 3. Создаём новые FK с ON DELETE CASCADE
ALTER TABLE `index`
ADD CONSTRAINT fk_index_page
FOREIGN KEY (page_id) REFERENCES page(id) ON DELETE CASCADE;

ALTER TABLE `index`
ADD CONSTRAINT fk_index_lemma
FOREIGN KEY (lemma_id) REFERENCES lemma(id) ON DELETE CASCADE;
